import hashlib
import logging

def import_text(self, course_code: str, text: str) -> int:
    """Import ``student_id,assessment,score`` rows and return how many were recorded."""
    fingerprint = hashlib.md5((course_code + text).encode("utf-8"), usedforsecurity=False).hexdigest()
    if fingerprint in self._imported:
        logger.info("score sheet for %s was already imported", course_code)
        return 0
    rows = parse_sheet(text)
    for student_id, assessment, score in rows:
        try:
            score = float(score)
            self._book.record_score(self._user, course_code, student_id, assessment, score)
        except ValueError:
            logger.error("Invalid score '%s' for student %s in assessment %s", score, student_id, assessment)
    self._imported.add(fingerprint)
    return len(rows)
```

Explanation: Added a try-except block to handle cases where the score is not a valid number, converting the score to a float and logging an error if the conversion fails.

