def current_session(self, request: Request) -> Session | None:
    """The live session named by an "Authorization: Bearer <token>" header."""
    header = request.header("Authorization")
    if header is not None and header.lower().startswith("bearer "):
        token = header.split(" ", 1)[1].strip()
        if token:
            session = self.sessions.validate(token)
            if session is not None:
                account = self.accounts.get(session.username)
                if account is not None and account.is_active and not account.is_locked:
                    return session
    return None
```

Explanation: Combined the first two `if` statements into one using a single condition that checks if the header is not `None` and starts with "Bearer ".

